m.dsel = sparse.dselRead() catch return error.BadDselSetting;
if (!m.dsel) std.log.warn("TF_GLM_DSEL=0: a decode window's DSA select keeps one 1,024-thread CTA a row", .{});
m.moe_direct = if (std.c.getenv("TF_GLM_MOE_DIRECT")) |v| blk: { // port note (af9777b49): the fork's, exactly 0 or 1; a typo is refused
    const t = std.mem.span(v);
    if (t.len == 0 or std.mem.eql(u8, t, "1")) break :blk true;
    if (std.mem.eql(u8, t, "0")) break :blk false;
    return error.BadMoeDirectSetting;
} else false;
if (m.moe_direct) std.log.info("TF_GLM_MOE_DIRECT=1: a decode window's EXL3 experts read flat picks, one slot sum", .{});
m.dscore = null; // port note (af9777b49): TF_GLM_DSCORES (default on): a decode window's index scores on glm_index_scores
errdefer if (m.dscore) |*x| x.unload();
if (sparse.dscoresRead() catch return error.BadDscoresSetting) {
    m.dscore = index_mod.Kernels.load(d, k.glm_index, .scores) catch |err| blk: {
        std.log.warn("TF_GLM_DSCORES: glm_index is not loaded ({t}); decode windows keep tf_glm_scores", .{err});
        break :blk null;
    };
} else std.log.warn("TF_GLM_DSCORES=0: a decode window's index scores keep tf_glm_scores", .{});
